package com.networkers.meetingautomation; import com.networkers.user.User; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface MeetingParticipantRepository extends JpaRepository<MeetingParticipant,Long>{ List<MeetingParticipant> findByGroupIdOrderByMemberFullNameAsc(Long groupId); Optional<MeetingParticipant> findByGroupYearAndGroupMonthAndMember(int year,int month,User member); boolean existsByGroupIdAndMemberId(Long groupId,Long memberId); @Query("select count(p) from MeetingParticipant p join MonthlyMeeting m on m.group=p.group where p.member=:member and m.status=com.networkers.meetingautomation.AutomatedMeetingStatus.COMPLETED") long countCompletedByMember(@Param("member") User member); @Modifying @Query("delete from MeetingParticipant p where p.group.id=:groupId") void deleteByGroupId(@Param("groupId") Long groupId); }
